import{_ as t,I as o,c as r,o as s,j as e,ap as n,a,J as d,ar as p}from"./chunks/framework.BVMg0REN.js";const B=JSON.parse('{"title":"总控台","description":"","frontmatter":{},"headers":[],"relativePath":"Features/MultiInstance.md","filePath":"zh/Features/MultiInstance.md","lastUpdated":1788771508000}'),c={name:"Features/MultiInstance.md"},u={id:"总控台",tabindex:"-1"};function h(g,l,m,_,b,f){const i=o("Badge");return s(),r("div",null,[e("h1",u,[l[0]||(l[0]=a("总控台")),d(i,{type:"warning",text:"多开"}),l[1]||(l[1]=a()),l[2]||(l[2]=e("a",{class:"header-anchor",href:"#总控台","aria-label":"Permalink to “总控台”"},"​",-1))]),l[3]||(l[3]=n('<div class="warning custom-block"><p class="custom-block-title">注意</p><ul><li><p>总控台仅用于监控和任务控制，新建/编辑连接请在主页界面「+」处操作。</p></li><li><p>V2.1.0及更高版本可1VN个模拟器，多开模式下不支持模拟器自启动，V2.1.0之前版本及需要自启动功能仍需要复制多个本体1V1操作。</p></li></ul></div><h2 id="界面介绍" tabindex="-1">界面介绍 <a class="header-anchor" href="#界面介绍" aria-label="Permalink to “界面介绍”">​</a></h2><p><img src="'+p+'" alt="多开界面"></p><h2 id="总控台-1" tabindex="-1">总控台 <a class="header-anchor" href="#总控台-1" aria-label="Permalink to “总控台”">​</a></h2><p>可查看所有连接的实时画面、连接状态，支持启动/停止任务。</p><p>多开操作用户必备好物，具体操作请向下⬇️浏览。</p><h2 id="多开操作" tabindex="-1">多开操作 <a class="header-anchor" href="#多开操作" aria-label="Permalink to “多开操作”">​</a></h2><h3 id="基础配置" tabindex="-1">基础配置 <a class="header-anchor" href="#基础配置" aria-label="Permalink to “基础配置”">​</a></h3><ul><li><p><strong>硬件</strong>：性能良好的电脑</p></li><li><p><strong>工具</strong>：了解ADB使用方法</p></li><li><p><strong>环境</strong>：模拟器需要支持多开，麻圆建议V2.1.0及之后</p></li><li><p><strong>文档</strong>：善用本手册+搜索引擎</p></li></ul><h3 id="连接操作" tabindex="-1">连接操作 <a class="header-anchor" href="#连接操作" aria-label="Permalink to “连接操作”">​</a></h3><ol><li><p>准备工作：复制模拟器及端口获取</p><ol><li><p>复制模拟器：</p><ul><li>MuMu：通过多开管理器复制已有模拟器（需先关闭），或新增安卓12模拟器并下载游戏。</li><li>Bluestacks：通过多开管理器创建新实例，编辑参数。</li><li>雷电：通过多开管理器复制模拟器<strong>连接配置</strong>：默认自动检测；手动时需下载platform tools并配置ADB路径，通过 <code>adb devices</code> 测试连接。</li></ul></li><li><p>获取模拟器端口：</p><ul><li><p>常见模拟器：</p><ul><li>MuMu 12：多开器右上角查看；</li><li>MuMu 5.0：模拟器设置-其他-ADB端口；</li><li>Bluestacks：模拟器设置→高级→Android调试（ADB）。</li></ul></li><li><p>通用方法：</p><ul><li>方案1（ADB命令）：启动模拟器后，在ADB所在目录执行<code>adb devices</code>（Windows CMD/PowerShell），输出中的 <code>127.0.0.1:&lt;端口&gt;</code> 或 <code>emulator-&lt;四位数字&gt;</code> 即为连接地址。</li><li>方案2（资源监视器）：Win+S搜“资源监视器”→网络选项卡→监听端口中找模拟器进程（如HD-Player.exe）的端口，或TCP连接中找adb.exe对应的远程端口。</li></ul></li></ul></li></ol></li><li><p>创建新实例进行连接和总控台</p><ol><li><p>新建实例及连接：</p><ul><li>点击主页右上方「+」按钮，自动新建实例。</li><li>点击右上角框内右起第二个 🔄<strong>&quot;刷新&quot;</strong>按钮，下拉框会自动检测并显示可用的模拟器端口，选择对应端口即可连接。</li><li>也可点击“自定义”按钮手动填写对应的ADB路径（即adb.exe文件的路径）、地址（<code>127.0.0.1:&lt;端口号&gt;</code>）。</li><li>在设置-连接设置 中打开“<strong>记住连接</strong>”选项，后续打开该实例即可默认连接当前的模拟器。</li></ul></li><li><p>总控台：</p><ul><li>入口在界面左侧边栏</li><li>可查看所有连接的实时画面、连接状态，支持启动/停止任务。</li></ul></li></ol></li></ol>',11))])}const P=t(c,[["render",h]]);export{B as __pageData,P as default};
